(50620,'chemistry','Critical temperature for O₂ is','154.3 K','Critical temperature for O₂ is 154.3 K\n\nReference: (NCERT Chemistry Class 11; Page No. 154; Table No. 5.4 )','Physical chemistry >> States of matter >> Liquefaction of gases and Critical parameters',NULL,'1','mcq','154.3 K','15.43 K','1.543 K','0.1543 K','NEW',NULL,NULL,NULL),
(50621,'chemistry','Critical pressure for O₂ is','50.4 bar','Critical pressure for O₂ is 50.4 bar\n\nReference: (NCERT Chemistry Class 11; Page No. 154; Table No. 5.4 )','Physical chemistry >> States of matter >> Liquefaction of gases and Critical parameters',NULL,'1','mcq','5.04 bar','50.4 bar','504 bar','0.504 bar','NEW',NULL,NULL,NULL),
(50622,'chemistry','Critical volume for O₂ is','0.0744 dm³ mol⁻¹','Critical volume for O₂ is 0.0744 dm³ mol⁻¹\n\nReference: (NCERT Chemistry Class 11; Page No. 154; Table No. 5.4 )','Physical chemistry >> States of matter >> Liquefaction of gases and Critical parameters',NULL,'1','mcq','0.744 dm³ mol⁻¹','7.44 dm³ mol⁻¹','74.4 dm³ mol⁻¹','0.0744 dm³ mol⁻¹','NEW',NULL,NULL,NULL),
(50623,'chemistry','Critical temperature for CO₂ is','304.10 K','Critical temperature for CO₂ is 304.10 K\n\nReference: (NCERT Chemistry Class 11; Page No. 154; Table No. 5.4 )','Physical chemistry >> States of matter >> Liquefaction of gases and Critical parameters',NULL,'1','mcq','273 K','304.10 K','30.410 K','6.041 K','NEW',NULL,NULL,NULL),
(50624,'chemistry','Critical pressure for CO₂ is','73.9 bar','Critical pressure for CO₂ is 73.9 bar \n\nReference: (NCERT Chemistry Class 11; Page No. 154; Table No. 5.4 )','Physical chemistry >> States of matter >> Liquefaction of gases and Critical parameters',NULL,'1','mcq','7.3 bar','1 bar','0.73 bar','73.9 bar','NEW',NULL,NULL,NULL),
