(460161,'chemistry','The critical pressure of a gas is given by\n\nP꜀=a/27b²\n\nWhere \nP꜀=Critical pressure, \na=Van der waal constant, \nb=Van der waal constant',NULL,NULL,'Physical Chemistry Formulae >> States of Matter >> Critical Pressure',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'DELETED',NULL,NULL,NULL),
(460162,'chemistry','Match the following with respect to critical pressure of a gas','P꜀-Critical pressure, b-van der waal constant, a-measure of attractive intermoleculer',NULL,'Physical Chemistry Formulae >> States of Matter >> Critical Pressure',NULL,'1','match','P꜀,Critical pressure','b,van der waal constant','a,measure of attractive inmoleculer',NULL,'DELETED',NULL,NULL,NULL),
(460163,'chemistry','Figure out the formula to calculate critical pressure of a gas from the following','P꜀=a/27b²',NULL,'Physical Chemistry Formulae >> States of Matter >> Critical Pressure',NULL,'1','fillup','P꜀,=,b²,27,/,a',NULL,NULL,NULL,'DELETED',NULL,NULL,NULL),
(460164,'chemistry','The critical temperature of a gas is given by\n\nT꜀=8a/27Rb\n\nWhere \nT꜀=Critical temperature, \na & b are van der waal\'s constant, \nR=Universal gas constant',NULL,NULL,'Physical Chemistry Formulae >> States of Matter >> Critical Temperature',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'DELETED',NULL,NULL,NULL),
(460165,'chemistry','Match the following with respect to critical temperature','T꜀-Critical temperature, b-van der waal constant, a-Measure of intermoleculer attractive forces, R-Universal gas constant',NULL,'Physical Chemistry Formulae >> States of Matter >> Critical Temperature',NULL,'1','match','T꜀,Critical temperature','b,van der waal constant','a,Measure of intermoleculer attractive forces','R,Universal gas constant','DELETED',NULL,NULL,NULL),
