(490145,'chemistry','Figure out the formula to determine PH of a solution obtained on hydrolysis of SA & WB','PH=7-1/2PK₆-1/2logC',NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Cationic Hydrolysis',NULL,'1','fillup','PH,=,7,-,1/2PK₆,-,1/2,logC',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(490146,'chemistry','The hydrolysis constant on hydrolysis of salt of SA & WB is given by\n\nKₕ=Kᵥᵥ/K₆\nh=√Kᵥᵥ/K₆c\n\nWhere \nh=Degree of hydrolysis, \nKₕ=Hydrolysis constant, \nKᵥᵥ=Ionic product of H₂O (10⁻¹⁴ at 298K), \nK₆=Base dissociation constant',NULL,NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Hydrolysis Constant in Cationic Hydrolysis',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(490147,'chemistry','Match the following with respect to Cationic Hydrolysis','h-Degree of hydrolysis, Kₕ-Hydrolysis constant, Kᵥᵥ-Ionic product of H₂O, K₆-Base dissociation constant',NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Hydrolysis Constant in Cationic Hydrolysis',NULL,'1','match','h,Degree of hydrolysis','Kₕ,Hydrolysis constant','Kᵥᵥ,Ionic product of H₂O','K₆,Base dissociation constant','NEW',NULL,NULL,NULL),
(490148,'chemistry','Figure out the formula to calculate degree of Cationic Hydrolysis','h=√Kᵥᵥ/K₆c',NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Hydrolysis Constant in Cationic Hydrolysis',NULL,'1','fillup','h,=,Kᵥᵥ,K₆,c,/,√',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(490149,'chemistry','The PH of solution obtained on hydrolysis of salt of WA & WB is given by\n\nPH=7+1/2(PKₐ-PK₆)\n\nWhere \nPKₐ=-logKₐ, \nPK₆=-logK₆, Kₐ & K₆ are acid and base dissociation constants resp.',NULL,NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> PH on Hydrolysis of Salt of Weak Acid & Weak Base',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(490150,'chemistry','Match the following with respect to WB & WA salt hydrolysis','PKₐ--logKₐ, PK₆--logK₆',NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> PH on Hydrolysis of Salt of Weak Acid & Weak Base',NULL,'1','match','PKₐ,-logKₐ','PK₆,-logK₆',NULL,NULL,'NEW',NULL,NULL,NULL),
(490151,'chemistry','Figure out the formula to calculate PH of salt hydrolysis of WA & WB','PH=7+1/2(PKₐ-PK₆)',NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> PH on Hydrolysis of Salt of Weak Acid & Weak Base',NULL,'1','fillup','PH,=,1/2,+,7,PKₐ,PK₆,-,(,)',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(490152,'chemistry','The hydrolysis constant of solution obtained on hydrolysis of salt of weak acid and weak base is given by\n\nKₕ=Kᵥᵥ/KₐxK₆\nh=√Kᵥᵥ/KₐK₆\n\nWhere \nKₕ=Hydrolysis constant, \nh=Degree of hydrolysis, \nKᵥᵥ=Ionic product of H₂O, \nKₐ=Acid dissociation constant',NULL,NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Hydrolysis constant of WA & WB Salt',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(490153,'chemistry','Match the following with respect to hydrolysis constant of salt of WA and WB','Kₕ-Hydrolysis constant, h-Degree of hydrolysis, Kᵥᵥ-10⁻¹⁴ at 298k, Kₐ-Acid dissociation constant, K₆-Base dissociation constant',NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Hydrolysis constant of WA & WB Salt',NULL,'1','match','Kₕ,Hydrolysis constant','Kᵥᵥ,10⁻¹⁴ at 298k','Kₐ,Acid dissociation constant','K₆,Base dissociation constant','NEW',NULL,NULL,NULL),
(490154,'chemistry','Figure out the formula to calculate degree of hydrolysis of salt of WA & WB','h=√Kᵥᵥ/KₐK₆',NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Hydrolysis constant of WA & WB Salt',NULL,'1','fillup','h=,√,/,Kᵥᵥ,Kₐ,K₆',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(490155,'chemistry','The PH of solution obtained on hydrolysis of salt of SA & SB is given by\n\nPH=7 Salt of strong acid and strong base do not hydrolyse',NULL,NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Hydrolysis of Salt of Strong Acid and Stron Base',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(490158,'chemistry','The PH of an acidic buffer is given by\n\nPH=PKₐ+log[Salt]/[Acid]\n\nWhere\n PKₐ= -log[Kₐ] of weak acid, \n[Salt]=Concentration of salt of acid and strong base, \n[Acid]=Concentration of weak acid',NULL,NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Acidic Buffer',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(490159,'chemistry','Match the following with respect to Acidic Buffer','PKₐ--log[Kₐ], [Salt]-Normality of salt of acid and strong base, [Acid]-Weak acid concentration',NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Acidic Buffer',NULL,'1','match','PKₐ,-log[Kₐ]','[Salt],Normality of salt of acid and strong base','[Acid],Weak acid concentration',NULL,'NEW',NULL,NULL,NULL),
(490160,'chemistry','Figure out the formula to calculate PH of an acidic buffer','PH=PKₐ+log[Salt]/[Acid]',NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Acidic Buffer',NULL,'1','fillup','PH,=PKₐ,+,log,[Salt],/,[Acid]',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(490161,'chemistry','The PH of an basic buffer is given by\n\nPOH=PK₆+log[Salt]/[Base]\nPH=PKᵥᵥ-POH\n\nWhere \nPKᵥᵥ=14 at 298k, \n[Base]=Concentration of weak base, \n[Salt]=Concentration of salt of weak base and strong acid, PK₆=-logK₆',NULL,NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Basic Buffer',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(490162,'chemistry','Match the following with respect to Basic Buffer','PK₆--logK₆, [Base]-Concentration of weak base, [Salt]-Concentration of salt of WB and SA,PKᵥᵥ-14 at 298k',NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Basic Buffer',NULL,'1','match','PK₆,-logK₆','[Base],Concentration of weak base','[Salt],Concentration of salt of WB and SA','PKᵥᵥ,14 at 298k','NEW',NULL,NULL,NULL),
(490163,'chemistry','Figure out the formula to calculate POH of a basic buffer','POH=PK₆+log[Salt]/[Base]',NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Basic Buffer',NULL,'1','fillup','POH,=,PK₆,+,log,[Salt],/,[Base]',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(490164,'chemistry','The solubility product of a salt dissociating as \n\nAₓBᵧ(i)⇌ xAʸ⁺+yBˣ⁻\nKₛₚ=[Aʸ⁺]ˣ[Bˣ⁻]ʸ\n\nWhere x and y are stoichiometric coefficient',NULL,NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Solubility Product',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(490165,'chemistry','Match the following with respect to solubility product','Kᵢₒₙᵢ꜀ ₚᵣₒₔᵤ꜀ₜ>Kₛₚ-precipitation occurs, K₁ₚ=Kₛₚ-solubility product, K₁ₚ<Kₛₚ-unaturated solution',NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Solubility Product',NULL,'1','match','Kᵢₒₙᵢ꜀ ₚᵣₒₔᵤ꜀ₜ>Kₛₚ,precipitation occurs','K₁ₚ=Kₛₚ,solubility product','K₁ₚ<Kₛₚ,unaturated solution',NULL,'NEW',NULL,NULL,NULL),
(490166,'chemistry','Figure out the formula to determine Kₛₚ of given salt AₓBᵧ⇌ xAʸ⁺+yBˣ⁻','Kₛₚ=[Aʸ⁺]ˣ[Bˣ⁻]ʸ',NULL,'Physical Chemistry Formulae >> Ionic Equilibrium >> Solubility Product',NULL,'1','fillup','Kₛₚ,=,[Aʸ⁺]ˣ,[Bˣ⁻]ʸ',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(500101,'chemistry','The equivalent wt of a substance is given by\n\nequivalent wt=Mw/n-factor\n\nn-factor=Change in oxidation number per mole=valency, \nMw=Moleculer weight',NULL,NULL,'Physical Chemistry Formulae >> Redox Reaction >> Equivalent wt',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(500102,'chemistry','Match the following with respect to equivalent weight','mole-valency, n-factor-Change in oxidation no. per mole, Mw-Moleculer wt',NULL,'Physical Chemistry Formulae >> Redox Reaction >> Equivalent wt',NULL,'1','match','mole,valency','n-factor,Change in oxidation no. per mole','Mw,Moleculer wt',NULL,'NEW',NULL,NULL,NULL),
(500103,'chemistry','Figure out the equivalent wt','Eq wt=Mw/n-factor',NULL,'Physical Chemistry Formulae >> Redox Reaction >> Equivalent wt',NULL,'1','fillup','Eq wt,=,Mw,n-factor,/',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(500104,'chemistry','The Number of Equivalents is given by\n\nn=W/E\n\nWhere n=no.of equivalents, \nW=wt of sample, E=quivalent wt of sample',NULL,NULL,'Physical Chemistry Formulae >> Redox Reaction >> Number of Equivalents',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
