INSERT INTO `ncert_book_pyq` (`unique_id`, `subject`, `question`, `answer`, `explanation`, `topic_name`, `chapter_name`, `difficulty`, `quiz_type`, `option_a`, `option_b`, `option_c`, `option_d`, `syllabus_update`, `ncert22_page`, `ncert23_page`, `image_url`) VALUES
(510125,'chemistry','For a solution of 2 volatile liquids, partial pressure of each component is given by\n\nP₁=P₁⁰x₁\nP₂=P₂⁰x₂\n\nWhere \nP₁ & P₂ are partial pressure of 1 & 2 resp. \nP₁⁰=Vapour pressure of pure component 1 at same temperature, \nP₂⁰=Vapour pressure of pure component 2 at same temperature, \nx₁ & x₂ are mole fractions of 1 & 2 component resp.',NULL,NULL,'Physical Chemistry Formulae >> Solutions >> Raoult\'s Law',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(510126,'chemistry','Match the following with respect to Raoult\'s Law','P₁⁰-Vapour pressure(VP) of pure component 1, P₂⁰-VP of pure component 2 at same temperature, x₁-Mole fraction of component 1, x₂-Mole fraction of component 2, P₁-Partial pressure of component 1',NULL,'Physical Chemistry Formulae >> Solutions >> Raoult\'s Law',NULL,'2','match','P₁⁰,Vapour pressure(VP) of pure component 1','P₂⁰,VP of pure component 2 at same temperature','x₁,Mole fraction of component 1','x₂,Mole fraction of component 2','NEW',NULL,NULL,NULL),
(510127,'chemistry','Figure out the formula to determine partial pressure of a component in a liq-liq solution','P₁=P₁⁰x₁',NULL,'Physical Chemistry Formulae >> Solutions >> Raoult\'s Law',NULL,'1','fillup','P₁,x₁,=,P₁⁰',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(510128,'chemistry','The total pressure over the solution phase in a liq-liq solution is given by\n\nPₜₒₜ=P₁+P₂\nPₜₒₜ=x₁P₁⁰+x₂P₂⁰\nPₜₒₜ=P₁⁰+(P₂⁰-P₁⁰)x₂\n\nWhere \nPₜₒₜ=Total Pressure, \nP₁&P₂ are partial pressures of comp. \n1 & 2 resp., x₁&x₂ are mole fraction of comp. \n1 & 2 resp., such that  x₁+x₂=1, P₁⁰&P₂⁰ are VP of comp 1 & 2 resp in pure state at same temperature',NULL,NULL,'Physical Chemistry Formulae >> Solutions >> Combination of Raoult\'s Law & Dalton\'s Law',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(510129,'chemistry','Match the following with respect to total pressure over solution','Pₜₒₜ-Total Pressure over solution, P₁⁰-VP of pure component 1 at same temperature, P₂⁰-VP of pure comp 2 at same temp., x₁-Mole fraction of comp 1 in solution, x₂-Mole fraction of comp 2 in solution',NULL,'Physical Chemistry Formulae >> Solutions >> Combination of Raoult\'s Law & Dalton\'s Law',NULL,'1','match','P₁⁰,VP of pure component 1 at same temperature','P₂⁰,VP of pure comp 2 at same temp.','x₁,Mole fraction of comp 1 in solution','x₂,Mole fraction of comp 2 in solution','NEW',NULL,NULL,NULL),
(510130,'chemistry','Figure out the formula to determine total pressure over the solution phase in a liquid-liquid solution','Pₜₒₜ=P₁⁰+(P₂⁰-P₁⁰)x₂',NULL,'Physical Chemistry Formulae >> Solutions >> Combination of Raoult\'s Law & Dalton\'s Law',NULL,'2','fillup','Pₜₒₜ,=,x₂,P₁⁰,+,-,P₁⁰,P₂⁰,(,)',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(510131,'chemistry','The relation between partial pressure of components over solution & mole fraction in vapour phase is given by\n\nP₁=y₁Pₜₒₜₐₗ\nP₂=y₂Pₜₒₜₐₗ\n\nWhere \nP₁ & P₂ are partial pressre of comp 1&2 resp., \ny₁ & y₂ are mole fractions of comp 1&2 in vapour phase, \nPₜₒₜₐₗ= P₁⁰+(P₂⁰-P₁⁰)x₂',NULL,NULL,'Physical Chemistry Formulae >> Solutions >> Liquid-Liquid Solution',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,'/ncert/pyq/physics/mcq/510131q.png'),
(510132,'chemistry','Match the following with respect to liquid-liquid solutions','P₁-Partial pressre of comp 1 over solution, y₁-mole fractions of comp 1 in vapour phase, Pₜₒₜₐₗ-Total partial pressure of components over solution',NULL,'Physical Chemistry Formulae >> Solutions >> Liquid-Liquid Solution',NULL,'1','match','P₁,Partial pressre of comp 1 over solution','y₁,mole fractions of comp 1 in vapour phase','Pₜₒₜₐₗ,Total partial pressure of components over solution',NULL,'NEW',NULL,NULL,'/ncert/pyq/physics/mcq/510132q.png'),
(510133,'chemistry','Figure out the relation between partial pressure and mole fraction in vapour phase','P₁=y₁Pₜₒₜₐₗ',NULL,'Physical Chemistry Formulae >> Solutions >> Liquid-Liquid Solution',NULL,'1','fillup','P₁,=,Pₜₒₜₐₗ,y₁',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(510134,'chemistry','The relative lowering of vapour pressure in a solution containing non-volatile solutes is given by\n\nRLVP=ΔP/P₀ =P₁⁰-P₁/P₁⁰ = x₂=n₂/n₁+n₂\nfor dilute solutions, n,>>n₂\nΔP/P₀ =n₂/n₁ =w₂xM₁/M₂xw₁\n\nWhere \nΔP=Lowering of vapour pressure, \nP₀=Vapour pressure of pure solvent, \nP₁=Vapour pressure of solution cont non-volatile solute, \nx₂=Mole fraction of solute, \nn₂=moles of solute, \nn₁=moles of solvent, \nw₂=wt of solute, \nw₁=wt of solvent, \nM₁=molar mass of solvent, \nM₂=molar mass of solute',NULL,NULL,'Physical Chemistry Formulae >> Solutions >> Relative Lowering of Vapour Pressure',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(510135,'chemistry','Match the following with respect to RLVP','n₂-moles of solute, n₁-moles of solvent, x₂-Mole fraction of solute, P₁-VP of solution cont non-volatile solute, P₀-VP of pure solvent',NULL,'Physical Chemistry Formulae >> Solutions >> Relative Lowering of Vapour Pressure',NULL,'2','match','n₂,moles of solute','n₁,moles of solvent','P₁,VP of solution cont non-volatile solute','P₀,VP of pure solvent','NEW',NULL,NULL,'/ncert/pyq/physics/mcq/510135q.png'),
(510136,'chemistry','Figure out the formula to calculate RLVP in a dilute solution','P₁⁰-P₁/P₁⁰ =n₂/n₁+n₂',NULL,'Physical Chemistry Formulae >> Solutions >> Relative Lowering of Vapour Pressure',NULL,'2','fillup','P₁⁰,-,P₁,/,P₁⁰, =,n₂,/,n₁+n₂',NULL,NULL,NULL,'NEW',NULL,NULL,'/ncert/pyq/physics/mcq/510136q.png'),
(510137,'chemistry','The elevation of boiling point in na solution is given by\n\nΔT₆=T₆-T₆⁰=K₆rn\nΔT₆=1000xw₂/M₂xw₁ x K₆\n\nWhere \nT₆=Boiling point of solution, \nT₆⁰=Boiling point of pure solvent, \nK₆=Mobl elevation constant or ebullioscopic constant, \nw₂=wt of solute, \nM₂=Molar mass of solute, \nw₁=wt of solvent in grams, m=molelity',NULL,NULL,'Physical Chemistry Formulae >> Solutions >> Elevation of Boiling Point',NULL,'2','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(510138,'chemistry','Match the following with respect to elevation of boiling point','T₆-BP of solution, T₆⁰-BP of pure solvent, K₆-ebullioscopic constant, m-molelity',NULL,'Physical Chemistry Formulae >> Solutions >> Elevation of Boiling Point',NULL,'2','match','T₆,BP of solution','T₆⁰,BP of pure solvent','K₆,ebullioscopic constant','m,molelity','NEW',NULL,NULL,NULL),
(510139,'chemistry','Figure out the formula to determine elevation of boiling point','ΔT=K*m',NULL,'Physical Chemistry Formulae >> Solutions >> Elevation of Boiling Point',NULL,'1','mcq','ΔT=K*m','ΔT=K*V','ΔT=K*T','ΔT=K*P','NEW',NULL,NULL,NULL),
(510140,'chemistry','The depression of freezing point on addition of non-volatile to a solvant is given by\n\nΔTբ=Tբ⁰-Tբ=Kբm\nΔTբ=kբ x w₁x1000/M₂xw₁\n\nWhere  \nΔ Tբ⁰=Freezing point(fp) of pure solvent, \nTբ=Freezing point of solution, \nKբ=Molal depression or cryoscopic constant, \nm=molality, \nw₁=wt of solute, \nM₂=Molar mass of solute, \nw₂=wt of solvent in grm',NULL,NULL,'Physical Chemistry Formulae >> Solutions >> Depression of Freezing Point',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(510141,'chemistry','Match the following with respect to depression in freezing point','Kբ-Cryoscopic constant, m-molality, Tբ⁰-Freezing point of pure solvent, Tբ-Freezing point of solution',NULL,'Physical Chemistry Formulae >> Solutions >> Depression of Freezing Point',NULL,'1','match','Kբ,Cryoscopic constant','m,molality','Tբ⁰,Freezing point of pure solvent','Tբ,Freezing point of solution','NEW',NULL,NULL,NULL),
(510142,'chemistry','Figure out the formula to calculate depression in freezing point','Tբ⁰-Tբ=Kբm',NULL,'Physical Chemistry Formulae >> Solutions >> Depression of Freezing Point',NULL,'1','fillup','Tբ⁰,-,Tբ,=,K,բm',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(510143,'chemistry','The ebullioscopic constant or molel evevation constant of a solvent is given by\n\nK₆= RxM₁xT₆⁰²/1000 x ΔHᵥₐₚ\n\nWhere \nR=Universal constant, \nM₁=Molar mass of solvent, \nT₆⁰=Boiling point of pure solvent, \nΔHᵥₐₚ=Enthalpy for vaporisation of solvent',NULL,NULL,'Physical Chemistry Formulae >> Solutions >> Ebullioscopic Constant',NULL,'2','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,'/ncert/pyq/physics/mcq/510143q.png'),
(510144,'chemistry','Match the following with respect to ebullioscopic constant','ΔHᵥₐₚ-Enthalpy for vaporisation of solvent, T₆⁰-BP of pure solvent, M₁-Molar mass of solvent, R-Universal constant, K₆-ebullioscopic constant',NULL,'Physical Chemistry Formulae >> Solutions >> Ebullioscopic Constant',NULL,'2','match','ΔHᵥₐₚ,Enthalpy for vaporisation of solvent','T₆⁰,BP of pure solvent','M₁,Molar mass of solvent','K₆,ebullioscopic constant','NEW',NULL,NULL,'/ncert/pyq/physics/mcq/510144q.png'),
(510145,'chemistry','Figure out the formula to determine ebullioscopic constant of a solvent','K₆= RxM₁xT₆⁰²/1000 x ΔHᵥₐₚ',NULL,'Physical Chemistry Formulae >> Solutions >> Ebullioscopic Constant',NULL,'2','fillup','K₆,=, RxM₁xT₆⁰²,/,1000, x, ΔHᵥₐₚ',NULL,NULL,NULL,'NEW',NULL,NULL,'/ncert/pyq/physics/mcq/510145q.png'),
(510146,'chemistry','The Cryoscopic or molel depression constant of a solvent is given by\n\nkբ=RxM₁xTբ² / 1000x  ΔHբᵤₛ\n\nWhere \nkբ=Cryoscopic constant, \nR=Universal gas constant, \nTբ⁰=Freezing point of pure solvent, \nΔHբᵤₛ=Enthalpy of fusion, \nM₁=Molar mass of solvent',NULL,NULL,'Physical Chemistry Formulae >> Solutions >> Cryoscopic Constant',NULL,'2','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,'/ncert/pyq/physics/mcq/510146q.png'),
(510147,'chemistry','Match the following with respect to cryoscopic constant of a solvent','kբ-Cryoscopic constant, Tբ⁰-Freezing point of pure solvent, ΔHբᵤₛ-Enthalpy of fusion, M₁-Molar mass of solvent, R-Universal gas constant',NULL,'Physical Chemistry Formulae >> Solutions >> Cryoscopic Constant',NULL,'2','match','kբ,Cryoscopic constant','Tբ⁰,Freezing point of pure solvent','ΔHբᵤₛ,Enthalpy of fusion','M₁,Molar mass of solvent','NEW',NULL,NULL,'/ncert/pyq/physics/mcq/510147q.png'),
(510148,'chemistry','Figure out the formula to calculate cryoscopic constant of a solvent','kբ=RxM₁xTբ² / 1000x  ΔHբᵤₛ',NULL,'Physical Chemistry Formulae >> Solutions >> Cryoscopic Constant',NULL,'2','fillup','kբ,=,R,x,M₁,x,Tբ², /, 1000,x,  ΔHբᵤₛ',NULL,NULL,NULL,'NEW',NULL,NULL,'/ncert/pyq/physics/mcq/510148q.png'),
(510149,'chemistry','The osmotic pressure of a solution is given by\n\nTl=CRT=n₂/V RT=w₂/M₂V RT\n\nWhere \nTl=Osmotic pressure, \nC=Molerity, \nT=Temperature in absolute scale(Kelvin), \nn₂=Moles of solute, \nV=Volume of solution(in l), \nw₂=wt of solute, \nM₂=Molar mass of solute',NULL,NULL,'Physical Chemistry Formulae >> Solutions >> Osmotic Pressure',NULL,'2','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(510150,'chemistry','Match the following with respect to osmotic pressure','Tl-Osmotic pressure, C-Molerity, R-Universal gas constant, T-Temperature in absolute scale',NULL,'Physical Chemistry Formulae >> Solutions >> Osmotic Pressure',NULL,'2','match','Tl,Osmotic pressure','C,Molerity','R,Universal gas constant','T,Temperature in absolute scale','NEW',NULL,NULL,NULL),
(510151,'chemistry','Figure out the formula to calculate osmotic pressure of a solution','Tl=CRT',NULL,'Physical Chemistry Formulae >> Solutions >> Osmotic Pressure',NULL,'1','fillup','Tl,R,T,C,=',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(510152,'chemistry','The van\'t hoff factor that accounts for extent of association and dissociation is given by\n\ni=Normal Molar mass/Abnormal Molar mass\n\ni=Obs colligative property/Collected colligative property\n\ni=Total no.of moles of particles after association|dissociation/No.of moles of particles before association|dissociation',NULL,NULL,'Physical Chemistry Formulae >> Solutions >> Van\'t Hoff Factor',NULL,'2','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(510153,'chemistry','Match the following with respect to van\'t hoff factor','i=1-No dissociation|Association, i>1-Dissociation, i<1-Association',NULL,'Physical Chemistry Formulae >> Solutions >> Van\'t Hoff Factor',NULL,'2','match','i=1,No dissociation|Association','i>1,Dissociation','i<1,Association',NULL,'NEW',NULL,NULL,NULL),
(510154,'chemistry','Figure out the formula of van\'t hoff factor','i=Normal Molar mass/Abnormal Molar mass',NULL,'Physical Chemistry Formulae >> Solutions >> Van\'t Hoff Factor',NULL,'1','fillup','i,=,Abnormal, Molar mass,/,Normal, Molar mass',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(510155,'chemistry','The relation between van\'t hoff factor and degree of dissociation is given by: for a r∝ⁿ AₓBᵧ⇌xA+yB\n\ni=1+(n-1)∝\n\nWhere \ni=van\'t hoff factor, \nn=x+y, \n∝=Degree of dissociation',NULL,NULL,'Physical Chemistry Formulae >> Solutions >> Relation Between i & Degree of Dissociation',NULL,'2','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,'/ncert/pyq/physics/mcq/510155q.png'),
(510156,'chemistry','Match the following with respect to dissociation of particle and i','i-van\'t hoff factor, n-x+y, ∝-Degree of dissociation',NULL,'Physical Chemistry Formulae >> Solutions >> Relation Between i & Degree of Dissociation',NULL,'2','match','i,van\'t hoff factor','n,x+y','∝,Degree of dissociation',NULL,'NEW',NULL,NULL,'/ncert/pyq/physics/mcq/510156q.png'),
(510157,'chemistry','Figure out the relation between van\'t hoff factor and degree of dissociation for an eqⁿ: AₓBᵧ⇌xA+yB','i=1+(n-1)∝',NULL,'Physical Chemistry Formulae >> Solutions >> Relation Between i & Degree of Dissociation',NULL,'2','fillup','i,=,1,+,(,n-1,),∝',NULL,NULL,NULL,'NEW',NULL,NULL,'/ncert/pyq/physics/mcq/510157q.png'),
(510158,'chemistry','The relation between van\'t hoff factor and degree of association for a r∝ⁿ: xA+yB⇌AxBy  is given by\n\ni=1+(1/n -1)β\n\nWhere \ni=van\'t hoff factor, \nn=x+y, \nβ=Degree of dissociation',NULL,NULL,'Physical Chemistry Formulae >> Solutions >> Relation Between i & Degree of Association',NULL,'2','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
