(520140,'chemistry','Limiting molar conductivity of an electrolyte that on dissociation given V₊ cations and V₋ anions is given by\n\nλ⁰ₘ=V₊λ⁰₊+V₋λ⁰₋\n\nWhere \nλ⁰₊- Limiting molar conductivity of cation, \nλ⁰₋-Limiting molar conductivity of anion, \nλ⁰ₘ- Limiting molar conductivity of electrolyte',NULL,NULL,'Physical Chemistry Formulae >> Electrochemistry >> Kohlrausch Law',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(520141,'chemistry','Match the following with respect to Kohlrausch Law','λ⁰ₘ-Limiting molar conductivity of electrolyte, λ⁰₋-Limiting molar conductivity of anion, λ⁰₊-Limiting molar conductivity of cation',NULL,'Physical Chemistry Formulae >> Electrochemistry >> Kohlrausch Law',NULL,'1','match','λ⁰ₘ,Limiting molar conductivity of electrolyte','λ⁰₋,Limiting molar conductivity of anion','λ⁰₊,Limiting molar conductivity of cation',NULL,'NEW',NULL,NULL,NULL),
(520142,'chemistry','Figure out the formula to determine Limiting molar conductivity of an electrolyte','λ⁰ₘ=V₊λ⁰₊+V₋λ⁰₋',NULL,'Physical Chemistry Formulae >> Electrochemistry >> Kohlrausch Law',NULL,'1','fillup','λ⁰ₘ,=,V₊λ⁰₊,+,V₋λ⁰₋',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(520143,'chemistry','The degree of dissociation of an electrolyte is given by\n\n∝=λₘᶜ/λₘ⁰\n\nWhere \n∝=Degree of dissociation, \nλₘᶜ= Molar conductivity at concentration c, \nλₘ⁰=Limiting Molar conductivity',NULL,NULL,'Physical Chemistry Formulae >> Electrochemistry >> Degree of Dissociation',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,'/ncert/pyq/physics/mcq/520143q.png'),
(520144,'chemistry','Match the following with respect to degree of dissociation','∝-Degree of dissociation, λₘᶜ-Molar conductivity at conc c, λₘ⁰-Limiting Molar conductivity',NULL,'Physical Chemistry Formulae >> Electrochemistry >> Degree of Dissociation',NULL,'1','match','∝,Degree of dissociation','λₘᶜ,Molar conductivity at conc c','λₘ⁰,Limiting Molar conductivity',NULL,'NEW',NULL,NULL,NULL),
(520145,'chemistry','Figure out the degree of dissociation of an electrolyte','∝=λₘᶜ/λₘ⁰',NULL,'Physical Chemistry Formulae >> Electrochemistry >> Degree of Dissociation',NULL,'1','fillup','∝,λₘ⁰,=,λₘᶜ,/',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(520146,'chemistry','The equilibrium constant for a weak electrolyte is given by\n\nKₐ=C∝²/1-∝ =Cλₘ²/(1- λₘ/λₘ⁰)λₘ⁰² =Cλₘ²/λₘ⁰(λₘ⁰-λₘ)\n\nWhere \nλₘ=Molar conductivity at concentration \nC, λₘ⁰=Limiting molar conductivity, \nC=Concentration',NULL,NULL,'Physical Chemistry Formulae >> Electrochemistry >> Equilibrium Constant for a weak electrolyte',NULL,'1','flashcard',NULL,NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
(520147,'chemistry','Match the following with respect to equilibrium constant for a weak electrolyte','Kₐ-Equilibrium constant, ∝-Degree of dissociation, λₘ-Molar conductivity, λₘ⁰-Limiting molar conductivity',NULL,'Physical Chemistry Formulae >> Electrochemistry >> Equilibrium Constant for a weak electrolyte',NULL,'1','match','Kₐ,Equilibrium constant','∝,Degree of dissociation','λₘ,Molar conductivity','λₘ⁰,Limiting molar conductivity','NEW',NULL,NULL,NULL),
(520148,'chemistry','Figure out the formula to calculate equilibrium constant for a weak electrolyte','Kₐ=Cλₘ²/λₘ⁰(λₘ⁰-λₘ)',NULL,'Physical Chemistry Formulae >> Electrochemistry >> Equilibrium Constant for a weak electrolyte',NULL,'1','fillup','Kₐ,=,C,λₘ²,/,λₘ⁰,(,λₘ⁰,-,λₘ,)',NULL,NULL,NULL,'NEW',NULL,NULL,NULL),
